js="""<script>
const esc=v=>String(v??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[m]));
const imgUrl=v=>{v=String(v||'').trim();if(!v)return '/assets/paint-placeholder.svg';if(v.startsWith('soudal-page:'))return '/api/soudal-image?url='+encodeURIComponent(v.slice(12));if(v.startsWith('/'))return v;if(/^https?:\\/\\//i.test(v))return v;return '/'+v.replace(/^\\.\\//,'')};
const money=v=>{let n=Number(v);return Number.isFinite(n)?n.toLocaleString('pt-PT',{style:'currency',currency:'EUR'}):'Consultar'};
const defaultCats=['Construção','Ferramentas','Jardim/Agricultura','Pinturas','Ferragens','Material Elétrico','Casa','Bricolage','Protecção Individual','Máquinas','Colas e Selantes','Sprays e Aerossóis'];
function renderCats(fams){let a=(fams||[]).filter(x=>x&&x.show_bottom!==false).slice(0,12);if(!a.length)a=defaultCats.map(name=>({name}));document.getElementById('mm-home-cats').innerHTML='<div class="mm-cats">'+a.map(f=>{let n=typeof f==='string'?f:f.name,icon=typeof f==='object'&&f.icon?f.icon:'/assets/paint-placeholder.svg',href=n==='Máquinas'?'catalogo-rida.html':'catalogo.html?cat='+encodeURIComponent(n);return `<a class="mm-cat" href="${href}"><img src="${esc(imgUrl(icon))}"><span>${esc(n)}</span></a>`}).join('')+'</div>'}
function renderHero(a){let s=(a||[]).find(x=>x&&x.enabled!==false)||{tag:'MarquesMater',title:'Tudo para os seus projetos',text:'Materiais de construção, ferramentas, tintas e muito mais. Qualidade e confiança num só lugar.',button:'Ver todas as categorias →',link:'catalogo.html',image:'assets/RCH072D6-B24.png'};document.getElementById('mm-home-hero').innerHTML=`<div class='mm-home-hero'><img class='hero-bg' src='${esc(imgUrl(s.image))}'><div class='container'><div class='mm-hero-copy'><div class='tag'>${esc(s.tag||'MarquesMater')}</div><h1>${esc(s.title||'Tudo para os seus projetos').replace(/\\n/g,'<br>')}</h1><p>${esc(s.text||'')}</p><a class='mm-hero-btn' href='${esc(s.link||'catalogo.html')}'>${esc(s.button||'Explorar catálogo →')}</a><div class='mm-hero-pills'><span class='mm-hero-pill'>✓ Pagamento seguro</span><span class='mm-hero-pill'>✓ Entregas rápidas</span><span class='mm-hero-pill'>✓ Produtos de qualidade</span><span class='mm-hero-pill'>✓ Apoio especializado</span></div></div></div></div>`}
function card(p){return `<article class='mm-product'><div class='mm-product-img'><img src='${esc(imgUrl(p.image||p.gallery?.[0]))}' alt='${esc(p.name)}' loading='lazy' onerror=\"this.src='/assets/paint-placeholder.svg'\"></div><div class='mm-product-body'><small>${esc(p.brand||p.family||'')}</small><h3>${esc(p.name||'Produto')}</h3><div class='mm-price'>${p.promo_price>0?money(p.promo_price):money(p.price)}</div><div class='mm-stock'>● Em stock</div><a class='mm-product-btn' href='produto-wc.html?slug=${encodeURIComponent(p.slug)}'>Ver produto</a></div></article>`}
function renderRida(a,m){let p=(a||[]).filter(x=>String(x.brand||'').toUpperCase()==='RIDA').slice(0,12),im=m?.image||'assets/RHD01075.png';document.getElementById('mm-home-rida').innerHTML=`<div class='mm-rida'><img class='mm-rida-bg' src='${esc(imgUrl(im))}'><div class='mm-rida-overlay'><div><div class='mm-eyebrow'>RIDA em destaque</div><h2>Máquinas RIDA em destaque</h2><p>Desempenho, durabilidade e tecnologia para os seus projetos.</p><a class='mm-orange' href='catalogo-rida.html'>Ver todos os produtos RIDA →</a></div></div></div><div class='mm-tabs'><span class='mm-tab active'>Todos</span><span class='mm-tab'>Kits</span><span class='mm-tab'>Berbequins</span><span class='mm-tab'>Martelos</span><span class='mm-tab'>Rebarbadoras</span><span class='mm-tab'>Jardim</span><span class='mm-tab'>Baterias</span><span class='mm-tab'>Carregadores</span></div><div class='mm-products'>${p.map(card).join('')}</div>`}
function renderBanners(a){a=Array.isArray(a)&&a.length?a:[{title:'Tintas NEUCE',text:'Cores que dão vida aos seus projetos.',image:'assets/paint-placeholder.svg',link:'catalogo.html?cat=Pinturas'},{title:'Soudal',text:'Soluções profissionais de colagem e selagem.',image:'assets/paint-placeholder.svg',link:'catalogo.html?brand=Soudal'},{title:'Tudo para o seu jardim',text:'Equipamentos, ferramentas e acessórios.',image:'assets/paint-placeholder.svg',link:'catalogo.html?cat=Jardim/Agricultura'}];document.getElementById('mm-home-banners').innerHTML=a.slice(0,3).map(x=>`<a class='mm-banner' href='${esc(x.link||'catalogo.html')}'><img src='${esc(imgUrl(x.image))}'><div class='mm-banner-copy'><h3>${esc(x.title||'Destaque')}</h3><p>${esc(x.text||'')}</p><span class='mm-orange'>Ver produtos →</span></div></a>`).join('')}
function renderBrands(a){let names=['RIDA','NEUCE','SOUDAL','VITO','BOSCH','Makita','STANLEY','DEWALT'],m=a||{};document.getElementById('mm-home-brands').innerHTML=names.map(n=>`<a class='mm-brand' href='catalogo.html?brand=${encodeURIComponent(n)}'>${m[n]?`<img src='${esc(imgUrl(m[n]))}' alt='${esc(n)}'>`:n}</a>`).join('')}
async function boot(){try{let site=await (await fetch('/api/site',{cache:'no-store'})).json(),r=await (await fetch('/api/products?limit=100',{cache:'no-store'})).json(),p=Array.isArray(r)?r:(r.products||r.items||[]),hp=site.settings?.homepage||{};renderHero(site.settings?.hero_slides);renderCats(site.families);renderRida(p,hp.rida_banner);let pro=p.filter(x=>Number(x.promo_price)>0).slice(0,6),fea=p.filter(x=>x.featured).slice(0,6);document.getElementById('mm-home-promos').innerHTML=pro.map(card).join('');document.getElementById('mm-home-featured').innerHTML=(fea.length?fea:p.slice(0,6)).map(card).join('');renderBanners(hp.promo_banners);renderBrands(hp.brand_logos)}catch(e){console.error(e)}}boot();
</script>"""

