s=ADMIN.read_text(encoding='utf-8')
if 'mm-home-media-admin' not in s:
    acss="""<style id='MM-HOME-MEDIA-ADMIN-CSS'>.mm-home-media-admin{margin-top:16px}.mm-media-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.mm-media-card{border:1px solid #e0e5e9;border-radius:12px;padding:13px;background:#fff}.mm-media-preview{height:120px;background:#f5f7f8;border-radius:10px;display:flex;align-items:center;justify-content:center;overflow:hidden;margin-bottom:9px}.mm-media-preview img{max-width:100%;max-height:100%;object-fit:contain}.mm-media-card input[type=file]{display:none}@media(max-width:700px){.mm-media-grid{grid-template-columns:1fr}}</style>"""
    s=s.replace('</head>',acss+'</head>',1)
    panel="""<div class='panel mm-home-media-admin'><div class='toolbar'><div><h3>🖼️ Imagens da página inicial</h3><p class='muted'>Troca aqui as imagens dos slides, banner RIDA, três banners promocionais e logótipos das marcas.</p></div></div><div id='homeMediaManager'></div></div>"""
    s=s.replace('<div class="hero-editor">',panel+'<div class="hero-editor">',1)
    start=s.find('function renderSlides()'); marker=s.find('function familyDefaultIcon',start)
    if start>=0 and marker>start:
        fn="""function renderSlides(){let a=DATA.settings?.hero_slides||[];$('slides').innerHTML=a.map((x,i)=>`<div class='slide'><div class='slide-head'><b>Slide ${i+1}</b><button class='btn danger' onclick='removeSlide(${i})'>Apagar</button></div><div class='grid' style='margin-top:10px'><input class='input full' data-si='${i}' data-k='title' placeholder='Título' value='${esc(x.title||'')}'><input class='input' data-si='${i}' data-k='tag' placeholder='Etiqueta' value='${esc(x.tag||'')}'><input class='input' data-si='${i}' data-k='button' placeholder='Texto do botão' value='${esc(x.button||'VER LOJA')}'><input class='input' data-si='${i}' data-k='link' placeholder='Link' value='${esc(x.link||'catalogo.html')}'><input class='input' data-si='${i}' data-k='image' placeholder='Imagem principal / URL' value='${esc(x.image||'')}'><input class='input' data-si='${i}' data-k='image2' placeholder='Segunda imagem / URL' value='${esc(x.image2||'')}'><label class='btn'>🖼️ Imagem principal<input type='file' accept='image/*' data-home-file='${i}:image'></label><label class='btn'>🖼️ Segunda imagem<input type='file' accept='image/*' data-home-file='${i}:image2'></label><textarea class='input full' data-si='${i}' data-k='text' rows='3' placeholder='Texto'>${esc(x.text||'')}</textarea></div></div>`).join('')||'<p class="muted">Sem slides.</p>';renderHomepageMedia()}function removeSlide(i){DATA.settings.hero_slides.splice(i,1);renderSlides()}function addSlide(){DATA.settings.hero_slides=DATA.settings.hero_slides||[];DATA.settings.hero_slides.push({enabled:true,tag:'MarquesMater',title:'Novo destaque',text:'',button:'VER LOJA',link:'catalogo.html',image:'',image2:''});renderSlides()}async function saveHome(){try{document.querySelectorAll('#slides [data-si]').forEach(e=>DATA.settings.hero_slides[+e.dataset.si][e.dataset.k]=e.value);for(const input of document.querySelectorAll('[data-home-file]'))if(input.files&&input.files[0]){let [i,k]=input.dataset.homeFile.split(':');let j=await upload(input.files[0]);DATA.settings.hero_slides[+i][k]=j.url}let hp=DATA.settings.homepage||{};hp.rida_banner={image:$('homeRidaUrl')?.value||''};hp.promo_banners=[1,2,3].map(n=>({title:$('promoTitle'+n)?.value||'',text:$('promoText'+n)?.value||'',image:$('promoUrl'+n)?.value||'',link:$('promoLink'+n)?.value||'catalogo.html'}));hp.brand_logos=hp.brand_logos||{};['RIDA','NEUCE','SOUDAL','VITO','BOSCH','Makita','STANLEY','DEWALT'].forEach(n=>{let e=$('brandUrl_'+n);if(e)hp.brand_logos[n]=e.value});await api('/api/admin/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({hero_slides:DATA.settings.hero_slides,homepage:hp})});alert('Página inicial e imagens guardadas.')}catch(e){alert(e.message)}}function renderHomepageMedia(){let hp=DATA.settings.homepage||{},rb=hp.rida_banner||{},pr=hp.promo_banners||[],br=hp.brand_logos||{},h='<div class="mm-media-grid">';h+=`<div class="mm-media-card"><h4>Banner RIDA</h4><div class="mm-media-preview"><img src="${esc(rb.image||'/assets/RHD01075.png')}"></div><input id="homeRidaUrl" class="input" value="${esc(rb.image||'')}" placeholder="URL / caminho"><label class="btn">Carregar imagem<input type="file" accept="image/*" onchange="uploadHomepageField(this,'homeRidaUrl')"></label></div>`;for(let n=1;n<=3;n++){let x=pr[n-1]||{};h+=`<div class="mm-media-card"><h4>Banner promocional ${n}</h4><div class="mm-media-preview"><img src="${esc(x.image||'/assets/paint-placeholder.svg')}"></div><input id="promoTitle${n}" class="input" value="${esc(x.title||'')}" placeholder="Título"><input id="promoText${n}" class="input" value="${esc(x.text||'')}" placeholder="Texto"><input id="promoUrl${n}" class="input" value="${esc(x.image||'')}" placeholder="URL / caminho"><input id="promoLink${n}" class="input" value="${esc(x.link||'catalogo.html')}" placeholder="Link"><label class="btn">Carregar imagem<input type="file" accept="image/*" onchange="uploadHomepageField(this,'promoUrl${n}')"></label></div>`}h+='</div><div class="panel" style="margin-top:12px"><h4>Logótipos das marcas</h4><div class="mm-media-grid">';['RIDA','NEUCE','SOUDAL','VITO','BOSCH','Makita','STANLEY','DEWALT'].forEach(n=>{h+=`<div class="mm-media-card"><b>${n}</b><div class="mm-media-preview" style="height:85px"><img src="${esc(br[n]||'')}" onerror="this.style.display='none'"></div><input id="brandUrl_${n}" class="input" value="${esc(br[n]||'')}" placeholder="URL / caminho"><label class="btn">Carregar logo<input type="file" accept="image/*" onchange="uploadHomepageField(this,'brandUrl_${n}')"></label></div>`});h+='</div></div>';$('homeMediaManager').innerHTML=h}async function uploadHomepageField(input,target){if(!input.files?.[0])return;try{let j=await upload(input.files[0]);$(target).value=j.url;renderHomepageMedia()}catch(e){alert(e.message)}}\n"""
        s=s[:start]+fn+s[marker:]
    s=s.replace('value="admin123"','value="admin"')
ADMIN.write_text(s,encoding='utf-8')
print('Homepage V10 applied')
